<?php
$error=null;
if(is_post()){
  try{
    if(post('action')==='request') { SalesWorkflowService::requestCancellationRefund(uid(),(int)post('job_id'),post('reason')); flash('ok','Cancellation refund request submitted for Executive Officer approval.'); }
    elseif(post('action')==='process') { SalesWorkflowService::processCancellationRefund((int)post('request_id'),uid(),post('method'),post('reference_no'),post('approver_employee_id'),post('approver_password')); flash('ok','Cancellation refund processed.'); }
    else throw new UserError('Unknown action.');
    redirect('cancellation_refunds');
  }catch(Throwable $e){$error=friendly_error($e);}
}
$openJobs=has_role('Executive Officer')?JobService::jobs('open'):[];
$pending=has_role('Executive Officer')?SalesWorkflowService::pendingCancellationRefunds():[];
$mine=has_role('Sales','Executive Officer')?SalesWorkflowService::cancellationRefundsForProcessing():[];
layout_start('Cancellation refunds','Downpayment refunds for cancelled jobs require Executive Officer approval, then Sales processing through an open drawer.'); echo error_box($error);
?>
<?php if(has_role('Executive Officer')):?><section class="panel"><h2>Request refund for a job</h2><form method="post" class="stack"><?=csrf_field()?><input type="hidden" name="action" value="request"><div><label>Open job</label><select name="job_id" required><option value="">Choose job</option><?php foreach($openJobs as $j):?><option value="<?=e($j['job_id'])?>"><?=e($j['job_ref_no'])?> · <?=e($j['client_name'])?></option><?php endforeach;?></select></div><div><label>Reason</label><textarea name="reason" required placeholder="Client cancelled job; refund recorded downpayment."></textarea></div><button class="btn btn-primary">Request cancellation refund</button></form><p class="muted small">This creates one request for each currently Recorded downpayment on the job. After every refund is processed, the job can be cancelled from its job page.</p></section><?php endif; ?>
<?php if(has_role('Executive Officer')):?><section class="panel"><h2>Pending approvals</h2><?php if(!$pending):?><div class="empty">No pending cancellation refunds.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Job / OR</th><th>Amount</th><th>Requester</th><th>Reason</th><th></th></tr></thead><tbody><?php foreach($pending as $x):?><tr><td><?=e($x['job_ref_no'])?><span class="sub"><?=e($x['or_number'])?></span></td><td class="num"><?=e(money($x['amount']))?></td><td><?=e($x['requester'])?></td><td><?=e($x['reason'])?></td><td><a class="btn btn-secondary btn-sm" href="<?=e(url('approvals'))?>">Review</a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<?php if(has_role('Sales','Executive Officer')):?><section class="panel"><h2>Approved refunds to process</h2><?php if(!$mine):?><div class="empty">No approved cancellation refunds are waiting for Sales processing.</div><?php else:?><div class="table-wrap"><table><thead><tr><th>Job / OR</th><th>Amount</th><th>Status</th><th>Process</th></tr></thead><tbody><?php foreach($mine as $x):?><tr><td><?=e($x['job_ref_no'])?><span class="sub"><?=e($x['or_number'])?></span></td><td class="num"><?=e(money($x['amount']))?></td><td><?=status_badge($x['status'])?></td><td><?php if($x['status']==='Approved'):?><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="process"><input type="hidden" name="request_id" value="<?=e($x['request_id'])?>"><select name="method"><option>Cash</option><option>GCash</option><option>Bank Transfer</option></select><input type="text" name="reference_no" placeholder="Reference if non-cash"><input type="text" name="approver_employee_id" placeholder="Executive Officer ID" required><input name="approver_password" type="password" placeholder="Executive Officer password" required><button class="btn btn-primary btn-sm">Process refund</button></form><?php else:?>Processed — no further action<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><?php endif;?>
<?php layout_end();
